import java.util.List;

class Box<T> {
    private T value;
    void set(T value) { this.value = value; }
    T get() { return value; }
}

class NumberBox<T extends Number> {
    T value;
    NumberBox(T value) { this.value = value; }
    double asDouble() { return value.doubleValue(); }   // allowed: T is bounded to Number
}

public class Main {
    static double sumAll(List<? extends Number> numbers) {   // producer: only reading
        double total = 0;
        for (Number n : numbers) total += n.doubleValue();
        return total;
    }

    public static void main(String[] args) {
        Box<String> box = new Box<>();
        box.set("hello");
        System.out.println(box.get());
        System.out.println(sumAll(List.of(1, 2, 3)));   // works with List<Integer> too
    }
}
